def split_otp_channel(apps, schema_editor):
    """The single "which channel delivers codes" choice (SmsSettings.otp_channel) becomes each channel's own OTP switch:
    the channel that was active stays on, the other starts off. A missing row keeps the model defaults (WhatsApp on,
    SMS off), which is what the old default 'whatsapp' meant."""
    SmsSettings = apps.get_model("api", "SmsSettings")
    WhatsAppSettings = apps.get_model("api", "WhatsAppSettings")
    sms = SmsSettings.objects.filter(pk=1).first()
    if sms is None:
        return
    on_sms = sms.otp_channel == "sms"
    SmsSettings.objects.filter(pk=1).update(otp_enabled=on_sms)
    WhatsAppSettings.objects.filter(pk=1).update(otp_enabled=not on_sms)


